#include "rr_combat.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "generated_combat_reference.h"
static unsigned failures;static size_t current;static double max_error;
#define CHECK(x) do{if(!(x)){if(failures<15)fprintf(stderr,"case %zu line %d: %s\n",current,__LINE__,#x);++failures;}}while(0)
#define COUNT(x) (sizeof(x)/sizeof((x)[0]))
static void near(double a,double b){double e=fabs(a-b);if(e>max_error)max_error=e;CHECK(isfinite(a)&&e<1e-10);}
static void vector(RRVec3 a,RRVec3 b){near(a.x,b.x);near(a.y,b.y);near(a.z,b.z);}
static RRLocalRacer load_actor(ActorFixture f){RRLocalRacer r={0};r.car.pos=f.pos;r.car.vel=f.vel;r.car.speed=f.speed;r.car.stun=f.stun;r.car.roll_time=f.roll;r.car.surge=f.surge;r.car.yaw=f.yaw;r.car.max_multiplier=1;r.hp=f.hp;r.wreck=f.wreck;r.fire_cd=f.fire_cd;r.race.finished=f.finished;r.is_player=f.player;r.visible=f.visible;return r;}
static void actor(const RRLocalRacer *r,ActorFixture f){vector(r->car.pos,f.pos);vector(r->car.vel,f.vel);near(r->car.speed,f.speed);near(r->car.stun,f.stun);near(r->car.roll_time,f.roll);near(r->car.surge,f.surge);near(r->car.yaw,f.yaw);near(r->hp,f.hp);near(r->wreck,f.wreck);near(r->fire_cd,f.fire_cd);CHECK(r->race.finished==f.finished&&r->is_player==f.player&&r->visible==f.visible);}
static RRShot load_shot(ShotFixture f,RRLocalRacer **r){RRShot s={0};s.owner=f.owner<0?NULL:r[f.owner];s.target=f.target<0?NULL:r[f.target];s.pos=f.pos;s.vel=f.vel;s.speed=f.speed;s.accel=f.accel;s.max_speed=f.max_speed;s.life=f.life;s.turn=f.turn;s.damage=f.damage;s.radius=f.radius;s.trail_time=f.trail_time;s.kind=(RRShotKind)f.kind;s.always=f.always;s.trail=f.trail;s.has_damage=f.has_damage;s.serial=f.serial;return s;}
static void shot(const RRShot *s,ShotFixture f,RRLocalRacer **r){CHECK(s->owner==(f.owner<0?NULL:r[f.owner])&&s->target==(f.target<0?NULL:r[f.target]));vector(s->pos,f.pos);vector(s->vel,f.vel);near(s->speed,f.speed);near(s->accel,f.accel);near(s->max_speed,f.max_speed);near(s->life,f.life);near(s->turn,f.turn);near(s->damage,f.damage);near(s->radius,f.radius);near(s->trail_time,f.trail_time);CHECK((int)s->kind==f.kind&&s->always==f.always&&s->trail==f.trail&&s->has_damage==f.has_damage&&s->serial==f.serial);}
typedef struct{RRLocalRacer **r;EventFixture events[12];unsigned count,world_calls;bool world_hit;} Context;
static int index_of(Context *c,RRLocalRacer *r){if(!r)return -1;for(int i=0;i<4;i++)if(c->r[i]==r)return i;return -2;}
static bool world(void *p,RRVec3 a,RRVec3 b,RRVec3 *hit){Context *c=p;(void)a;(void)b;++c->world_calls;*hit=rr_v3(7,88,9);return c->world_hit;}
static void notice(void *p,unsigned event,const RRShot *s,RRLocalRacer *r,RRVec3 point){Context *c=p;CHECK(c->count<12);if(c->count>=12)return;c->events[c->count++]=(EventFixture){event,s->serial,index_of(c,r),point};if(event==RR_SHOT_RACER_IMPACT)(void)rr_combat_shot_damage(s,r,true);}
typedef struct{RRLocalRacer **r;unsigned count,items[4][2];} EmpContext;
static void emp_notice(void *p,RRLocalRacer *r,unsigned result){EmpContext *c=p;unsigned i=0;while(i<4&&c->r[i]!=r)++i;CHECK(c->count<4);if(c->count<4){c->items[c->count][0]=i;c->items[c->count++][1]=result;}}
int main(void){
 for(current=0;current<COUNT(damage_fixtures);++current){const DamageFixture *f=&damage_fixtures[current];RRLocalRacer r=load_actor(f->before);CHECK(rr_combat_damage(&r,f->amount,(RRShotKind)f->kind,f->active)==f->flags);actor(&r,f->after);}
 for(current=0;current<COUNT(default_fixtures);++current){const DefaultFixture *f=&default_fixtures[current];RRLocalRacer r=load_actor(f->before);RRShot s={0};s.damage=f->amount;s.has_damage=f->has_damage;CHECK(rr_combat_shot_damage(&s,&r,true)==f->flags);actor(&r,f->after);}
 for(current=0;current<COUNT(emp_fixtures);++current){const EmpFixture *f=&emp_fixtures[current];RRLocalRacer actors[4];RRLocalRacer *r[4];for(unsigned i=0;i<4;++i){actors[i]=load_actor(f->before[i]);r[i]=actors+i;}EmpContext c={0};c.r=r;CHECK(rr_combat_emp(rr_v3(0,100,0),r,4,true,emp_notice,&c)==f->count);CHECK(c.count==f->notice_count);for(unsigned i=0;i<c.count;++i)CHECK(c.items[i][0]==f->notices[i][0]&&c.items[i][1]==f->notices[i][1]);for(unsigned i=0;i<4;++i)actor(r[i],f->after[i]);}
 for(current=0;current<COUNT(dodge_fixtures);++current){const DodgeFixture *f=&dodge_fixtures[current];RRCar c;rr_car_reset(&c,rr_v3(0,0,0),f->yaw,f->speed);c.vel=rr_v3(2,3,4);rr_car_dodge(&c,f->side);near(c.speed,f->immediately[0]);vector(c.vel,rr_v3(f->immediately[1],f->immediately[2],f->immediately[3]));near(c.roll_time,f->immediately[4]);near(c.surge,f->immediately[5]);CHECK(c.roll_direction==(int)f->immediately[6]);RRInput input={0};rr_car_step(&c,input,f->dt);near(c.roll_time,f->after[0]);near(c.surge,f->after[1]);CHECK((c.roll_time>0)==f->dodging);rr_car_place(&c,rr_v3(0,100,0),0,0);CHECK(c.roll_time==0&&c.surge==0);}
 unsigned event_count=0,world_count=0,purges=0;
 for(current=0;current<COUNT(step_fixtures);++current){const StepFixture *f=&step_fixtures[current];RRLocalRacer actors[4];RRLocalRacer *r[4]={0};for(unsigned i=0;i<f->nr;++i){actors[i]=load_actor(f->actors[i]);r[i]=actors+i;}RRShot shots[5];for(unsigned i=0;i<f->ns;++i)shots[i]=load_shot(f->before[i],r);size_t ns=f->ns;Context c={0};c.r=r;c.world_hit=f->world_hit;if(f->purge){size_t n=rr_shots_purge(shots,&ns,rr_v3(0,100,0),95,r[0],notice,&c);CHECK(n==f->purged);purges+=(unsigned)n;}else rr_shots_step(shots,&ns,r,f->nr,f->dt,f->floor,world,&c,notice,&c);CHECK(ns==f->after_count&&c.world_calls==f->world_calls&&c.count==f->event_count);for(unsigned i=0;i<ns;++i)shot(shots+i,f->after[i],r);for(unsigned i=0;i<f->nr;++i)actor(r[i],f->after_actors[i]);for(unsigned i=0;i<c.count&&i<f->event_count;++i){CHECK(c.events[i].event==f->events[i].event&&c.events[i].serial==f->events[i].serial&&c.events[i].victim==f->events[i].victim);vector(c.events[i].point,f->events[i].point);}event_count+=c.count;world_count+=c.world_calls;rr_shots_clear(&ns);CHECK(ns==0);}
 printf("COMBAT_SUMMARY damage_cases=%zu default_cases=%zu emp_cases=%zu dodge_cases=%zu projectile_cases=%zu events=%u world_queries=%u purged=%u max_error=%.17g shot_bytes=%zu failures=%u\n",COUNT(damage_fixtures),COUNT(default_fixtures),COUNT(emp_fixtures),COUNT(dodge_fixtures),COUNT(step_fixtures),event_count,world_count,purges,max_error,sizeof(RRShot),failures);
 return failures?EXIT_FAILURE:EXIT_SUCCESS;
}
